 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: no raid here';
   var bad=[], g, p, rd, pa, r, NK={}, k, oSend=netSend, E0=null, h0, h1;
   for(k in NET) NK[k]=NET[k];
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     if(g.sim) return 'SKIP: the fixture raid is a sim raid';
     p=g.player; p.iv=99;
     rd=g.ents.filter(function(x){ return x.kind==='raider'&&!x.merc&&!x.friendlyPC&&x.hp>0&&!x.downed&&!x.boss; })[0];
     if(!rd) return 'SKIP: staging: no pillager in the fixture raid';
     E0=g.ents; g.ents=[rd]; rd.x=p.x+60; rd.y=p.y; rd.hp=rd.maxhp=2000; rd.roll=0; rd.rollCd=99;
     // the host's own round
     rd.rig='heavy'; rd.armor=100; rd.stopT=0; g.bullets.length=0;
     g.bullets.push({x:rd.x,y:rd.y,vx:0.01,vy:0,dmg:62,life:0.5,player:true,owner:p,tint:'#fff',thru:0});
     updateBullets(0.001); h0=rd.stopT; g.bullets.length=0;
     if(!(h0>0)) return 'SKIP: staging: the host round did not stop the armoured pillager';
