     if(r!=='shot') return 'SKIP: staging: the host did not take player 2 shot ('+r+')';
     h1=rd.stopT;
     if(!(h1>0)) bad.push('player 2 62 round into the armoured pillager did not stop him (host round: '+h0+', armour left '+rd.armor+')');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
