     try{ netSend=oSend; for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; if(g&&E0) g.ents=E0; if(g) g.bullets.length=0; }catch(_h){}
     try{ __endRaid('abandon'); }catch(_e){}
